-- Microsoft Clarity (теплові карти і записи сесій) для сайтів клієнтів: ID проєкту Clarity — публічний, не секрет
ALTER TABLE products ADD COLUMN clarity_id TEXT NOT NULL DEFAULT '';
INSERT INTO changelog (title, body, created_at) VALUES ('Теплова карта сайту (Microsoft Clarity)', 'У «Пульсі сайту» тепер можна підключити Microsoft Clarity — безкоштовні теплові карти (куди клікають, до куди гортають) і записи сесій (відео, як людина ходила по сайту). Як: створи проєкт на clarity.microsoft.com (вкажи адресу сайту) → скопіюй Project ID (Settings → Overview) → встав у «Пульс сайту» → «Промпт: поставити Clarity» → у чат Claude Code сайту. Далі кнопка «Теплова карта ↗» відкриває Clarity цього сайту. Поля форм Clarity маскує, телефони й імена не записуються. Перші карти — за кілька годин після встановлення.', datetime('now'));
